// PWA basics: pages must carry a viewport and theme-color, link the
// web app manifest, and the manifest plus its icons must be served.
// The 192/512 icons are generated by build.rs from the same base64
// sources as the favicons, so their presence here also proves the
// build-time generation covers the manifest sizes.

mod common;

use axum::{
    body::Body,
    http::{Request, StatusCode},
};
use tower::ServiceExt;

async fn body_string(resp: axum::response::Response) -> String {
    let body = axum::body::to_bytes(resp.into_body(), usize::MAX)
        .await
        .unwrap();
    String::from_utf8(body.to_vec()).unwrap()
}

async fn get(app: &axum::Router, uri: &str) -> axum::response::Response {
    app.clone()
        .oneshot(Request::builder().uri(uri).body(Body::empty()).unwrap())
        .await
        .unwrap()
}

#[tokio::test]
async fn test_manifest_served_and_valid() {
    let app = common::create_test_app().await;

    let resp = get(&app, "/static/manifest.json").await;
    assert_eq!(resp.status(), StatusCode::OK);
    let ct = resp
        .headers()
        .get("content-type")
        .unwrap()
        .to_str()
        .unwrap()
        .to_string();
    assert!(ct.contains("json"), "manifest content type: {}", ct);
    let body = body_string(resp).await;
    let manifest: serde_json::Value =
        serde_json::from_str(&body).expect("manifest should be valid JSON");
    assert_eq!(manifest["name"], "Brunnylol");
    assert_eq!(manifest["short_name"], "Brunnylol");
    assert_eq!(manifest["start_url"], "/");
    assert_eq!(manifest["theme_color"], "#1a1a2e");
    assert_eq!(manifest["background_color"], "#1a1a2e");

    let icons = manifest["icons"].as_array().expect("manifest icons array");
    let sizes: Vec<&str> = icons.iter().filter_map(|i| i["sizes"].as_str()).collect();
    assert!(
        sizes.contains(&"192x192"),
        "manifest needs a 192 icon: {:?}",
        sizes
    );
    assert!(
        sizes.contains(&"512x512"),
        "manifest needs a 512 icon: {:?}",
        sizes
    );

    // Every icon the manifest references must actually be served.
    for icon in icons {
        let src = icon["src"].as_str().expect("icon src");
        let resp = get(&app, src).await;
        assert_eq!(
            resp.status(),
            StatusCode::OK,
            "icon {} should be served",
            src
        );
        let ct = resp
            .headers()
            .get("content-type")
            .unwrap()
            .to_str()
            .unwrap()
            .to_string();
        assert!(
            ct.contains("image/png"),
            "icon {} content type: {}",
            src,
            ct
        );
    }
}

#[tokio::test]
async fn test_pages_carry_pwa_meta_and_manifest_link() {
    let app = common::create_test_app().await;

    let resp = get(&app, "/").await;
    assert_eq!(resp.status(), StatusCode::OK);
    let body = body_string(resp).await;
    assert!(
        body.contains(r#"name="viewport" content="width=device-width, initial-scale=1""#),
        "pages should carry a viewport meta"
    );
    assert!(
        body.contains(r##"name="theme-color" content="#1a1a2e""##),
        "pages should carry a theme-color meta"
    );
    assert!(
        body.contains(r#"rel="manifest" href="/static/manifest.json""#),
        "pages should link the web app manifest"
    );
}
